#include <iostream>
using namespace std;

long long required_moves(int disks) {
    if (disks == 0) {
        return 0;
    }
    return 2 * required_moves(disks - 1) + 1;
}

void move_tower(int disks, int source, int destination, int spare) {
    if (disks == 0) {
        return;
    }
    move_tower(disks - 1, source, spare, destination);

    cout << source << ' ' << destination << '\n';
    move_tower(disks - 1, spare, destination, source);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int disks;
    cin >> disks;
    cout << required_moves(disks) << '\n';
    move_tower(disks, 1, 3, 2);
    return 0;
}

